PRAGMA foreign_keys = ON;

-- Migration 0004: Cau truc lo trinh hoc CEFR A1-C1 (levels -> units -> vocabulary + sentences)
-- Noi dung do Claude (Anthropic) bien soan truc tiep, nguyen goc, khong sao chep tu sach/khoa hoc nao.
-- Khong xoa/doi bang content_topics/content_phrases cu de khong pha vo API dang chay.

CREATE TABLE content_levels (
  id TEXT PRIMARY KEY,
  code TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL,
  description TEXT NOT NULL,
  level_order INTEGER NOT NULL
);

CREATE TABLE content_units (
  id TEXT PRIMARY KEY,
  level_id TEXT NOT NULL REFERENCES content_levels(id),
  title TEXT NOT NULL,
  description TEXT NOT NULL,
  icon TEXT NOT NULL,
  target_persona TEXT NOT NULL,
  unit_order INTEGER NOT NULL
);

CREATE TABLE content_level_vocabulary (
  id TEXT PRIMARY KEY,
  unit_id TEXT NOT NULL REFERENCES content_units(id),
  word TEXT NOT NULL,
  ipa TEXT,
  meaning_vi TEXT NOT NULL,
  example_en TEXT NOT NULL,
  example_vi TEXT NOT NULL,
  word_order INTEGER NOT NULL
);

CREATE TABLE content_unit_sentences (
  id TEXT PRIMARY KEY,
  unit_id TEXT NOT NULL REFERENCES content_units(id),
  english TEXT NOT NULL,
  vietnamese_hint TEXT NOT NULL,
  audio_tip TEXT,
  focus_grammar TEXT,
  sentence_order INTEGER NOT NULL
);

CREATE INDEX idx_units_level ON content_units(level_id, unit_order);
CREATE INDEX idx_level_vocab_unit ON content_level_vocabulary(unit_id, word_order);
CREATE INDEX idx_unit_sentences_unit ON content_unit_sentences(unit_id, sentence_order);




